INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1750, 'invest', '/ɪnˈvest/', 'verb', '{"zh-TW":["投資"],"en":["to put money into something for profit","to put money into something to make a profit"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"vest","meaning":"clothe/cover (覆蓋)"},"logic":"把資金包進某事物中，即「投資」。"}', 'invest in / invest time / invest money; invest in stocks/real estate / invest time', '[{"en":"She invested her savings in stocks.","zh-TW":"她把積蓄投資在股票上。"},{"en":"The company invested heavily in research.","zh-TW":"公司在研究方面投入了大量資金。"},{"en":"She invested heavily in technology stocks.","zh-TW":"她大量投資科技股。"},{"en":"The company plans to invest in new equipment.","zh-TW":"公司計劃投資新設備。"}]', '{"noun":"investment","noun2":"investor","verb":"invest"}', NULL, 2, 1750, NULL),
(1751, 'investigate', '/ɪnˈvestɪɡeɪt/', 'verb', '{"zh-TW":["調查；研究"],"en":["to carry out a systematic examination"]}', NULL, 'investigate a case/claim/complaint', '[{"en":"Police are investigating the cause of the fire.","zh-TW":"警方正在調查火災原因。"},{"en":"The committee will investigate the allegations.","zh-TW":"委員會將調查這些指控。"}]', '{"noun":"investigation, investigator","verb":"investigate","adjective":"investigative"}', NULL, 4, 1751, NULL),
(1752, 'investment', '/ɪnˈvɛstmənt/', 'noun', '{"zh-TW":["投資"],"en":["money put into something to generate profit or income"]}', NULL, 'return on investment / long-term investment', '[{"en":"The company made a significant investment in technology.","zh-TW":"公司在技術方面進行了重大投資。"},{"en":"Diversifying your investment portfolio reduces risk.","zh-TW":"分散投資組合可降低風險。"}]', '{"verb":"invest","noun":"investor","adjective":"invested"}', NULL, 4, 1752, 378),
(1753, 'invitation', 'ˌɪnvɪˈteɪʃən', 'noun', '{"zh-TW":["邀請；請帖","邀請函"],"en":["a written or spoken request","a card asking someone to attend"]}', NULL, 'formal invitation/send an invitation', '[{"en":"We sent invitations to all stakeholders.","zh-TW":"我們向所有利益相關者發送了邀請。"}]', '{"verb":"invite","adjective":"inviting","adverb":"invitingly"}', NULL, 4, 1753, 379),
(1754, 'invite', 'ɪnˈvaɪt', 'verb', '{"zh-TW":["邀請；招待","引起"],"en":["to ask someone to attend","to cause something to happen"]}', NULL, 'invite to a meeting/event', '[{"en":"We would like to invite you to our launch event.","zh-TW":"我們想邀請您參加我們的發布活動。"}]', '{"noun":"invitation","adjective":"inviting","adverb":"invitingly"}', NULL, 2, 1754, NULL),
(1755, 'invoice', '/ˈɪnvɔɪs/', 'noun, verb', '{"zh-TW":["發票；帳單","開發票"],"en":["a bill for goods or services","to send an invoice"]}', NULL, 'issue/send an invoice / pay an invoice', '[{"en":"Please send the invoice to our accounting department.","zh-TW":"請將發票發送到我們的會計部門。"},{"en":"We will invoice you at the end of the month.","zh-TW":"我們會在月底向您開具發票。"}]', '{"noun":"invoice","verb":"invoke"}', NULL, 3, 1755, 145),
(1756, 'involve', '/ɪnˈvɑːlv/', 'verb', '{"zh-TW":["涉及；包含；使參與"],"en":["to include as a necessary part; to cause someone to participate"]}', NULL, 'involve someone in / be involved in', '[{"en":"The project involves a team of 20 people.","zh-TW":"該項目涉及一個20人的團隊。"},{"en":"She was deeply involved in the planning process.","zh-TW":"她深入參與了規劃過程。"}]', '{"noun":"involvement","verb":"involve","adjective":"involved"}', NULL, 3, 1756, 146),
(1757, 'IPO', '/ˌaɪ piː ˈoʊ/', 'noun', '{"zh-TW":["首次公開募股"],"en":["initial public offering; first sale of company shares to the public"]}', NULL, 'launch an IPO / IPO price / IPO prospectus / pre-IPO', '[{"en":"The company raised $500 million through its IPO.","zh-TW":"公司通過首次公開募股籌集了5億美元。"},{"en":"Investors were eager to buy shares in the highly anticipated IPO.","zh-TW":"投資者急於購買備受期待的首次公開募股的股票。"}]', '{"full form":"initial public offering"}', NULL, 1, 1757, NULL),
(1758, 'island', '/ˈaɪlənd/', 'noun', '{"zh-TW":["島嶼"],"en":["a piece of land surrounded by water"]}', NULL, 'island resort / remote island', '[{"en":"The conference is at an island resort.","zh-TW":"會議在一個島嶼度假村舉行。"},{"en":"We source materials from the island.","zh-TW":"我們從島上採購原料。"}]', '{"noun":"island","noun2":"islander"}', NULL, 2, 1758, NULL),
(1759, 'isolate', '/ˈaɪsəleɪt/', 'verb', '{"zh-TW":["隔離；孤立"],"en":["to separate from others"]}', NULL, 'isolate a problem/variable / socially isolated', '[{"en":"Scientists isolated the virus in the laboratory.","zh-TW":"科學家在實驗室中分離了病毒。"},{"en":"The town was isolated by the flood.","zh-TW":"小鎮因洪水而被孤立。"}]', '{"noun":"isolation","verb":"isolate","adjective":"isolated"}', NULL, 3, 1759, NULL),
(1760, 'issue', '/ˈɪʃuː/', 'noun, verb', '{"zh-TW":["議題；問題","發行；發布"],"en":["a topic for discussion; a problem","to officially provide or publish"]}', NULL, 'address an issue / issue a statement/warning', '[{"en":"We need to address this issue immediately.","zh-TW":"我們需要立即解決這個問題。"},{"en":"The company issued a press release.","zh-TW":"公司發布了一份新聞稿。"}]', '{"noun":"issue","verb":"issue"}', NULL, 2, 1760, 147),
(1761, 'issuer', '/ˈɪʃuːər/', 'noun', '{"zh-TW":["發行方；發行人"],"en":["an entity that creates and offers financial instruments for sale"]}', NULL, 'bond issuer / securities issuer / identify the issuer', '[{"en":"The issuer is responsible for the accuracy of the prospectus.","zh-TW":"發行方對招股書的準確性負責。"},{"en":"A reputable issuer lowers investor risk in the primary market.","zh-TW":"知名的發行方降低了一級市場投資者的風險。"}]', '{"verb":"issue","adjective":"issued"}', NULL, 2, 1761, NULL),
(1762, 'item', '/ˈaɪtəm/', 'noun', '{"zh-TW":["項目；物品"],"en":["an individual thing or unit","a single thing in a list or group"]}', '{"root":{"text":"item","meaning":"also (同樣地)"},"logic":"源自拉丁語 item（同樣地），用於列舉清單中的各項。"}', 'item number / luxury item; agenda item / item on the list', '[{"en":"Each item is clearly labeled with a price.","zh-TW":"每件商品都清楚標示價格。"},{"en":"This is a popular item among young customers.","zh-TW":"這是年輕顧客中的熱門商品。"},{"en":"The first item on the agenda is the budget.","zh-TW":"議程上的第一項是預算。"},{"en":"All items must be checked before shipping.","zh-TW":"所有物品在出貨前必須檢查。"}]', '{"verb":"itemize","noun":"item"}', NULL, 1, 1762, NULL),
(1763, 'iteration', '/ˌɪtəˈreɪʃən/', 'noun', '{"zh-TW":["迭代"],"en":["a repeated cycle of development in which improvements are made each time"]}', NULL, 'agile iteration / product iteration / rapid iteration', '[{"en":"Each iteration delivers a working increment of the product.","zh-TW":"每次迭代交付產品的一個可工作的增量。"},{"en":"Rapid iteration allows the team to respond quickly to feedback.","zh-TW":"快速迭代使團隊能夠快速響應反饋。"}]', '{"verb":"iterate","adjective":"iterative"}', NULL, 3, 1763, NULL),
(1764, 'itinerary', '/aɪˈtɪnəreri/', 'noun', '{"zh-TW":["行程；旅程"],"en":["a planned route or schedule of travel"]}', NULL, 'travel itinerary / detailed itinerary', '[{"en":"Please send me the detailed itinerary for the trip.","zh-TW":"請把旅行的詳細行程發給我。"},{"en":"The itinerary includes visits to three cities.","zh-TW":"行程包括參觀三個城市。"}]', '{"noun":"itinerary"}', NULL, 3, 1764, NULL),
(1765, 'jargon', '/ˈdʒɑːrɡən/', 'noun', '{"zh-TW":["行話；專業術語"],"en":["specialized language used by a particular profession"]}', NULL, 'technical/legal/business jargon', '[{"en":"Please avoid using technical jargon in the report.","zh-TW":"請避免在報告中使用技術行話。"},{"en":"The contract is full of legal jargon.","zh-TW":"合同中充滿了法律術語。"}]', '{"noun":"jargon"}', NULL, 2, 1765, NULL),
(1766, 'jealous', '/ˈdʒeləs/', 'adjective', '{"zh-TW":["嫉妒的"],"en":["feeling resentment toward someone because of their advantages"]}', '{"root":{"text":"zeal","meaning":"zeal/fervor (熱情)"},"suffix":{"text":"-ous","meaning":"full of (充滿)"},"logic":"充滿強烈情感（嫉妒）的。"}', 'jealous of / feel jealous', '[{"en":"She was jealous of her sister''s success.","zh-TW":"她嫉妒姐姐的成功。"},{"en":"Don''t be jealous of other people.","zh-TW":"不要嫉妒他人。"}]', '{"noun":"jealousy"}', NULL, 3, 1766, NULL),
(1767, 'jeopardize', '/ˈdʒepərdaɪz/', 'verb', '{"zh-TW":["危及；損害"],"en":["to put something in danger of being harmed or lost"]}', NULL, 'jeopardize safety/chances/career', '[{"en":"His reckless behavior could jeopardize the entire project.","zh-TW":"他魯莽的行為可能危及整個項目。"},{"en":"Don''t jeopardize your career over a minor disagreement.","zh-TW":"不要因為小分歧而危及你的職業生涯。"}]', '{"noun":"jeopardy","verb":"jeopardize"}', NULL, 4, 1767, NULL),
(1768, 'job', '/dʒɑːb/', 'noun', '{"zh-TW":["工作；職位"],"en":["a paid position of employment"]}', NULL, 'job opening / job description / full-time job', '[{"en":"She applied for a job at the marketing firm.","zh-TW":"她向那家行銷公司申請了一份工作。"},{"en":"The company posted a new job opening online.","zh-TW":"公司在網上發布了一個新職位。"}]', '{"noun":"job","adjective":"jobless"}', NULL, 1, 1768, NULL),
(1769, 'join', '/dʒɔɪn/', 'verb', '{"zh-TW":["加入；連接"],"en":["to become a member of; to connect"]}', NULL, 'join a company/team/organization', '[{"en":"He joined the company in 2019.","zh-TW":"他於2019年加入公司。"},{"en":"Would you like to join us for lunch?","zh-TW":"你想和我們一起吃午飯嗎？"}]', '{"noun":"joint","verb":"join","adjective":"joint"}', NULL, 1, 1769, NULL),
(1770, 'joint', '/dʒɔɪnt/', 'adjective, noun', '{"zh-TW":["共同的；聯合的","關節；接合處"],"en":["shared by two or more parties","a point of connection"]}', NULL, 'joint venture / joint effort / joint account', '[{"en":"The two companies formed a joint venture.","zh-TW":"兩家公司成立了一家合資企業。"},{"en":"This was a joint effort between departments.","zh-TW":"這是各部門的共同努力。"}]', '{"noun":"joint","adjective":"joint","adverb":"jointly"}', NULL, 2, 1770, NULL),
(1771, 'journal', '/ˈdʒɜːrnl/', 'noun', '{"zh-TW":["期刊；日誌"],"en":["a scholarly publication; a daily record"]}', NULL, 'academic journal / keep a journal', '[{"en":"The research was published in a leading journal.","zh-TW":"該研究發表在一份頂尖期刊上。"},{"en":"She keeps a journal of her daily activities.","zh-TW":"她記錄每天活動的日誌。"}]', '{"noun":"journal, journalism, journalist"}', NULL, 3, 1771, NULL),
(1772, 'journey', 'ˈdʒɜːrni', 'noun', '{"zh-TW":["旅程；旅途","歷程"],"en":["travel from one place to another","a process or experience"]}', NULL, 'business journey/long journey', '[{"en":"The business journey has been challenging.","zh-TW":"商業旅程充滿挑戰。"}]', '{"verb":"journey","adjective":"journeying"}', NULL, 3, 1772, NULL),
(1773, 'judge', '/dʒʌdʒ/', 'noun', '{"zh-TW":["法官；裁判","判斷；評價"],"en":["a person who decides cases in court","to form an opinion about"]}', NULL, 'judge a case / pass judgment; judge by/from / pass judgment', '[{"en":"The judge sentenced him to five years.","zh-TW":"法官判他五年。"},{"en":"Don''t judge people by appearances.","zh-TW":"不要以貌取人。"},{"en":"Don''t judge a book by its cover.","zh-TW":"不要以貌取人。"},{"en":"The judge ruled in favor of the plaintiff.","zh-TW":"法官判原告勝訴。"}]', '{"verb":"judge","noun2":"judgment","noun":"judge, judgment","adjective":"judgmental"}', NULL, 2, 1773, NULL),
(1774, 'judgment', '/ˈdʒʌdʒmənt/', 'noun', '{"zh-TW":["判斷力；判決"],"en":["the ability to make sensible decisions; a court decision"]}', NULL, 'good/poor judgment / exercise judgment', '[{"en":"She showed good judgment in handling the situation.","zh-TW":"她在處理情況時表現出良好的判斷力。"},{"en":"The court will deliver its judgment next week.","zh-TW":"法院將在下週做出判決。"}]', '{"noun":"judgment, judge","verb":"judge","adjective":"judgmental"}', NULL, 3, 1774, NULL),
(1775, 'jump', '/dʒʌmp/', 'verb', '{"zh-TW":["跳躍；暴漲"],"en":["to push oneself into the air","to increase suddenly"]}', NULL, 'jump start / price jump', '[{"en":"Stock prices jumped 10% today.","zh-TW":"股價今天暴漲了10%。"},{"en":"We need to jump-start the project.","zh-TW":"我們需要快速啟動這個專案。"}]', '{"verb":"jump","noun":"jump"}', NULL, 1, 1775, NULL),
(1776, 'jurisdiction', '/ˌdʒʊrɪsˈdɪkʃn/', 'noun', '{"zh-TW":["管轄權；司法權"],"en":["the official power to make legal decisions"]}', NULL, 'fall under/within jurisdiction', '[{"en":"This case falls outside our jurisdiction.","zh-TW":"這個案件不在我們的管轄範圍內。"},{"en":"The dispute was settled by the local jurisdiction.","zh-TW":"爭議由當地司法機關解決。"}]', '{"noun":"jurisdiction","adjective":"jurisdictional"}', NULL, 4, 1776, 797),
(1777, 'jury', '/ˈdʒʊri/', 'noun', '{"zh-TW":["陪審團"],"en":["a group of people who decide if someone is guilty"]}', NULL, 'jury duty / jury trial', '[{"en":"The jury found him guilty.","zh-TW":"陪審團裁定他有罪。"},{"en":"She was called for jury duty.","zh-TW":"她被叫去擔任陪審員。"}]', '{"noun2":"juror"}', NULL, 1, 1777, NULL),
(1778, 'just', '/dʒʌst/', 'adjective, adverb', '{"zh-TW":["【主要意義-副詞】只是；剛剛；僅僅","【次要意義-形容詞】公正的；正直的；合理的","【次要意義-副詞】恰好地；正好地"],"en":["[primary - adverb] only; recently; barely","[secondary - adjective] based on fairness and moral rightness","[secondary - adverb] exactly or precisely"]}', NULL, 'just cause / a just decision / just in time / just about / justice', '[{"en":"The committee ensured that all employees received a just and fair evaluation.","zh-TW":"委員會確保所有員工都得到公正且公平的評估。"},{"en":"The new inventory system arrived just in time to prevent a supply shortage.","zh-TW":"新庫存系統恰好及時到達，防止了供應短缺。"},{"en":"His decision to dismiss the employee was considered just under the circumstances.","zh-TW":"在這種情況下，他解雇員工的決定被認為是合理的。"}]', '{"noun":"justice, justification","adverb":"justly"}', '形容詞 just = 「公正的/合理的」（a just cause = 正當理由）是高階用法；just in time（恰好及時/準時制）是製造業和物流業的 TOEIC 必考詞彙。', 1, 1778, NULL),
(1779, 'just-in-time', '/ˌdʒʌst ɪn ˈtaɪm/', 'noun', '{"zh-TW":["即時生產；零庫存管理"],"en":["an inventory strategy minimizing stock by ordering only as needed"]}', NULL, 'just-in-time manufacturing / just-in-time delivery / adopt just-in-time', '[{"en":"Just-in-time manufacturing reduced storage costs dramatically.","zh-TW":"即時生產大幅降低了倉儲成本。"},{"en":"The just-in-time system is vulnerable to supply chain disruptions.","zh-TW":"即時生產系統容易受到供應鏈中斷的影響。"}]', '{"abbreviation":"JIT"}', NULL, 4, 1779, NULL),
(1780, 'justice', '/ˈdʒʌstɪs/', 'noun', '{"zh-TW":["正義；司法"],"en":["fairness; the legal system"]}', NULL, 'justice system / bring to justice', '[{"en":"They demand justice for the victims.","zh-TW":"他們要求為受害者伸張正義。"},{"en":"The criminal was brought to justice.","zh-TW":"罪犯被繩之以法。"}]', NULL, NULL, 3, 1780, NULL),
(1781, 'justify', '/ˈdʒʌstɪfaɪ/', 'verb', '{"zh-TW":["證明...合理；為...辯護"],"en":["to show that something is reasonable or right"]}', NULL, 'justify a decision/expense/action', '[{"en":"How can you justify such a large expense?","zh-TW":"你怎麼能證明這麼大的開支是合理的？"},{"en":"The results justify our investment.","zh-TW":"結果證明我們的投資是合理的。"}]', '{"noun":"justification","verb":"justify","adjective":"justifiable, justified"}', NULL, 3, 1781, 380),
(1782, 'Kanban', '/ˈkænbæn/', 'noun', '{"zh-TW":["看板；看板方法"],"en":["a visual workflow management system using cards on a board to track tasks"]}', NULL, 'Kanban board / Kanban method / Kanban workflow', '[{"en":"The team used a Kanban board to visualize work in progress.","zh-TW":"團隊使用看板視覺化進行中的工作。"},{"en":"Kanban helps identify bottlenecks in the workflow quickly.","zh-TW":"看板幫助快速識別工作流程中的瓶頸。"}]', NULL, NULL, 2, 1782, NULL),
(1783, 'keen', '/kiːn/', 'adjective', '{"zh-TW":["熱衷的；敏銳的"],"en":["eager or enthusiastic; sharp or acute"]}', NULL, 'keen interest / keen on / keen sense', '[{"en":"She is keen on learning new languages.","zh-TW":"她熱衷於學習新語言。"},{"en":"He has a keen eye for detail.","zh-TW":"他對細節有敏銳的眼光。"}]', '{"noun":"keenness","adjective":"keen","adverb":"keenly"}', NULL, 1, 1783, NULL),
(1784, 'keep', '/kiːp/', 'verb', '{"zh-TW":["保持；持續"],"en":["to continue to have","to remain in a state"]}', NULL, 'keep up / keep in mind', '[{"en":"Keep in mind the deadline is Friday.","zh-TW":"請記住截止日期是週五。"},{"en":"Keep up the good work.","zh-TW":"繼續保持好的表現。"}]', '{"verb":"keep","noun":"keeper"}', NULL, 1, 1784, NULL),
(1785, 'key', '/kiː/', 'noun, adjective', '{"zh-TW":["鑰匙；關鍵","關鍵的"],"en":["a small metal instrument for opening locks; essential","of crucial importance"]}', NULL, 'key factor/role/issue / the key to success', '[{"en":"Communication is the key to a successful partnership.","zh-TW":"溝通是成功合作的關鍵。"},{"en":"She plays a key role in the organization.","zh-TW":"她在組織中扮演著關鍵角色。"}]', '{"noun":"key","adjective":"key"}', NULL, 1, 1785, NULL),
(1786, 'keynote', '/ˈkiːnoʊt/', 'noun, adjective', '{"zh-TW":["主旨；基調"],"en":["the main theme or most important point; a principal speech"]}', NULL, 'keynote speech/speaker/address', '[{"en":"The CEO delivered the keynote speech at the conference.","zh-TW":"執行長在會議上發表了主題演講。"},{"en":"Innovation was the keynote of the event.","zh-TW":"創新是這次活動的主旨。"}]', '{"noun":"keynote"}', NULL, 3, 1786, NULL),
(1787, 'kick', '/kɪk/', 'verb', '{"zh-TW":["踢；啟動"],"en":["to strike with the foot","to start something"]}', NULL, 'kick off / kick start', '[{"en":"Let''s kick off the meeting.","zh-TW":"讓我們開始會議吧。"},{"en":"The campaign kicks off next Monday.","zh-TW":"活動下週一開始。"}]', '{"verb":"kick","noun":"kick","noun2":"kickoff"}', NULL, 1, 1787, NULL),
(1788, 'kickback', '/ˈkɪkbæk/', 'noun', '{"zh-TW":["回扣；賄賂"],"en":["illegal payment in exchange for favorable treatment or contracts"]}', NULL, 'investigate kickbacks / illegal kickback scheme', '[{"en":"The manager was dismissed for accepting kickbacks from suppliers.","zh-TW":"該經理因接受供應商回扣而被解雇。"},{"en":"A whistleblower exposed the kickback scheme to the compliance team.","zh-TW":"舉報者向合規團隊揭露了回扣計劃。"}]', NULL, NULL, 3, 1788, NULL),
(1789, 'kill', '/kɪl/', 'verb', '{"zh-TW":["殺死；終止"],"en":["to cause death","to end something"]}', NULL, 'kill time / overkill', '[{"en":"They decided to kill the project.","zh-TW":"他們決定終止這個專案。"},{"en":"That level of detail is overkill.","zh-TW":"那種程度的細節太過頭了。"}]', '{"verb":"kill","noun":"killer","noun2":"killing"}', NULL, 1, 1789, NULL),
(1790, 'kind', '/kaɪnd/', 'noun', '{"zh-TW":["種類；善良的"],"en":["a type or category","friendly and generous"]}', NULL, 'kind of / all kinds of', '[{"en":"What kind of work do you do?","zh-TW":"你做什麼類型的工作？"},{"en":"She is very kind to new employees.","zh-TW":"她對新員工很友善。"}]', '{"noun":"kind","adjective":"kind","noun2":"kindness","adverb":"kindly"}', NULL, 1, 1790, NULL),
(1791, 'kindergarten', '/ˈkɪndərɡɑːrtən/', 'noun', '{"zh-TW":["幼稚園"],"en":["a school for young children aged 4-6"]}', NULL, 'kindergarten teacher / start kindergarten', '[{"en":"My son starts kindergarten next year.","zh-TW":"我兒子明年開始上幼稚園。"},{"en":"She teaches kindergarten.","zh-TW":"她教幼稚園。"}]', NULL, NULL, 4, 1791, NULL),
(1792, 'king', '/kɪŋ/', 'noun', '{"zh-TW":["國王；巨頭"],"en":["a male ruler","the most important person"]}', NULL, 'content is king / king of the market', '[{"en":"In digital marketing, content is king.","zh-TW":"在數位行銷中，內容為王。"},{"en":"They are the king of the electronics market.","zh-TW":"他們是電子產品市場的霸主。"}]', '{"noun":"king","noun2":"kingdom"}', NULL, 1, 1792, NULL),
(1793, 'kitchen', '/ˈkɪtʃɪn/', 'noun', '{"zh-TW":["廚房"],"en":["a room where food is prepared"]}', NULL, 'office kitchen / kitchen staff', '[{"en":"The office kitchen is on the second floor.","zh-TW":"辦公室廚房在二樓。"},{"en":"Kitchen staff must wear gloves.","zh-TW":"廚房人員必須戴手套。"}]', '{"noun":"kitchen"}', NULL, 3, 1793, NULL),
(1794, 'kitchenette', '/ˌkɪtʃɪˈnɛt/', 'noun', '{"zh-TW":["小廚房；簡易廚房"],"en":["a small kitchen area within a room"]}', NULL, 'room with kitchenette / use the kitchenette', '[{"en":"The extended stay room comes with a kitchenette.","zh-TW":"長住房配有小廚房。"},{"en":"The kitchenette includes a microwave and mini-fridge.","zh-TW":"小廚房配有微波爐和小冰箱。"}]', NULL, NULL, 4, 1794, NULL),
(1795, 'knee', '/niː/', 'noun', '{"zh-TW":["膝蓋"],"en":["the joint in the middle of the leg"]}', NULL, 'knee-jerk reaction / bring to its knees', '[{"en":"Don''t make knee-jerk decisions.","zh-TW":"不要做出衝動的決定。"},{"en":"The recession brought the industry to its knees.","zh-TW":"經濟衰退重創了這個產業。"}]', '{"noun":"knee"}', NULL, 1, 1795, NULL),
(1796, 'knife', '/naɪf/', 'noun', '{"zh-TW":["刀"],"en":["a tool with a sharp blade for cutting"]}', NULL, 'knife edge / under the knife', '[{"en":"The decision is on a knife edge.","zh-TW":"這個決定懸而未決。"},{"en":"Budgets are always under the knife.","zh-TW":"預算總是面臨削減。"}]', '{"noun":"knife","plural":"knives"}', NULL, 2, 1796, NULL),
(1797, 'knock', '/nɒk/', 'verb', '{"zh-TW":["敲；敲打"],"en":["to hit a surface to attract attention"]}', NULL, 'knock on the door / knock down', '[{"en":"Opportunity doesn''t knock twice.","zh-TW":"機會不會敲兩次門。"},{"en":"They knocked down the old warehouse.","zh-TW":"他們拆除了舊倉庫。"}]', '{"verb":"knock","noun":"knock","noun2":"knockout"}', NULL, 2, 1797, NULL),
(1798, 'know', '/noʊ/', 'verb', '{"zh-TW":["知道；認識"],"en":["to be aware of","to be familiar with"]}', NULL, 'know-how / as far as I know', '[{"en":"We have the technical know-how.","zh-TW":"我們有技術專業知識。"},{"en":"As far as I know, the deal is still on.","zh-TW":"據我所知，交易還在進行中。"}]', '{"verb":"know","noun":"knowledge","adjective":"known","noun2":"know-how"}', NULL, 1, 1798, NULL),
(1799, 'know-how', '/ˈnoʊˌhaʊ/', 'noun', '{"zh-TW":["專業技術；實際知識"],"en":["practical knowledge and expertise in a field"]}', NULL, 'technical know-how / transfer know-how / accumulate know-how', '[{"en":"The company''s competitive advantage lies in its manufacturing know-how.","zh-TW":"公司的競爭優勢在於其製造專業技術。"},{"en":"Staff training helps transfer know-how across generations of employees.","zh-TW":"員工培訓有助於在各代員工之間傳遞專業知識。"}]', NULL, NULL, 3, 1799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1800, 'knowledge', '/ˈnɑːlɪdʒ/', 'noun', '{"zh-TW":["知識；了解"],"en":["facts, information, and skills acquired through experience or education"]}', NULL, 'to my knowledge / common knowledge / knowledge of', '[{"en":"A good knowledge of English is essential for this job.","zh-TW":"良好的英語知識對這份工作至關重要。"},{"en":"To my knowledge, no one has complained.","zh-TW":"據我所知，沒有人抱怨。"}]', '{"noun":"knowledge","adjective":"knowledgeable"}', NULL, 3, 1800, NULL),
(1801, 'kosher', '/ˈkəʊʃər/', 'adjective', '{"zh-TW":["符合猶太飲食規定的"],"en":["conforming to Jewish dietary laws"]}', NULL, 'kosher meal / kosher certified', '[{"en":"Kosher meals are available on request for the flight.","zh-TW":"航班上可根據要求提供符合猶太教規的餐食。"},{"en":"The hotel has a kosher-certified kitchen.","zh-TW":"飯店設有符合猶太教規認證的廚房。"}]', NULL, NULL, 2, 1801, NULL),
(1802, 'KPI', '/ˌkeɪ piː ˈaɪ/', 'noun', '{"zh-TW":["關鍵績效指標"],"en":["key performance indicator; a measurable value showing how effectively goals are met"]}', NULL, 'set KPIs / meet KPIs / KPI dashboard / track KPIs', '[{"en":"Each team member has individual KPIs aligned to company goals.","zh-TW":"每位團隊成員都有與公司目標一致的個人關鍵績效指標。"},{"en":"The KPI showed a 20% improvement in customer satisfaction.","zh-TW":"關鍵績效指標顯示客戶滿意度提升了20%。"}]', '{"full form":"key performance indicator"}', NULL, 1, 1802, NULL),
(1803, 'KYC', '/keɪ waɪ siː/', 'noun', '{"zh-TW":["了解您的客戶；客戶身份驗證"],"en":["Know Your Customer procedures to verify client identity"]}', NULL, 'complete KYC / KYC requirements', '[{"en":"Banks must complete KYC procedures for new account holders.","zh-TW":"銀行必須對新帳戶持有人完成客戶身份驗證程序。"},{"en":"KYC requirements prevent financial fraud and money laundering.","zh-TW":"客戶身份驗證要求防止金融詐騙和洗錢。"}]', NULL, NULL, 1, 1803, NULL),
(1804, 'label', '/ˈleɪbl/', 'noun', '{"zh-TW":["標籤","貼標籤；稱呼"],"en":["a piece of paper attached to an object giving information about it","a piece of paper giving information about something","to attach a label to; to categorize"]}', '{"root":{"text":"label","meaning":"strip/ribbon (帶子)"},"logic":"源自古法語，指貼在物品上的資訊帶。"}', 'price label / brand label; product label / label as', '[{"en":"Check the label for washing instructions.","zh-TW":"查看標籤上的洗滌說明。"},{"en":"The label shows the country of origin.","zh-TW":"標籤顯示原產地。"},{"en":"Check the label for the ingredients list.","zh-TW":"查看標籤上的成分表。"},{"en":"The product was labeled as organic.","zh-TW":"該產品被標註為有機產品。"}]', '{"verb":"label","noun":"label"}', NULL, 2, 1804, NULL),
(1805, 'labor', '/ˈleɪbər/', 'noun', '{"zh-TW":["勞動；勞工"],"en":["physical or mental work; workers as a group"]}', NULL, 'labor market / labor force / labor costs', '[{"en":"The company is trying to reduce labor costs.","zh-TW":"公司正在努力降低勞動成本。"},{"en":"There is a shortage in the labor market.","zh-TW":"勞動市場存在短缺。"}]', '{"noun":"labor, laborer","verb":"labor","adjective":"laborious"}', NULL, 2, 1805, 381),
(1806, 'laboratory', '/ləˈbɒrətɔːri/', 'noun', '{"zh-TW":["實驗室"],"en":["a room equipped for scientific experiments and research"]}', NULL, 'science laboratory / laboratory research', '[{"en":"Students conducted experiments in the chemistry laboratory.","zh-TW":"學生在化學實驗室進行了實驗。"},{"en":"The laboratory is equipped with the latest research instruments.","zh-TW":"實驗室配備了最新的研究儀器。"}]', '{"adjective":"laboratory","abbreviation":"lab"}', NULL, 4, 1806, NULL),
(1807, 'lack', '/læk/', 'noun', '{"zh-TW":["缺乏","缺乏；不足"],"en":["the state of being without something","the state of not having something"]}', '{"root":{"text":"lack","meaning":"want/deficiency (缺乏)"},"logic":"指不足或缺少某物的狀態。"}', 'lack of / for lack of / lack confidence; lack of experience/funding/resources', '[{"en":"The project failed due to lack of funding.","zh-TW":"專案因缺乏資金而失敗。"},{"en":"He lacks the experience for this role.","zh-TW":"他缺乏擔任這個角色的經驗。"},{"en":"The project failed due to a lack of funding.","zh-TW":"該項目因缺乏資金而失敗。"},{"en":"He lacks the experience needed for this role.","zh-TW":"他缺乏這個職位所需的經驗。"}]', '{"verb":"lack","adjective":"lacking","noun":"lack"}', NULL, 1, 1807, NULL),
(1808, 'lactose-free', '/ˈlæktoʊs friː/', 'adjective', '{"zh-TW":["無乳糖的"],"en":["not containing lactose, a sugar found in milk"]}', NULL, 'lactose-free milk / lactose-free option', '[{"en":"Lactose-free milk is available for guests with intolerances.","zh-TW":"無乳糖牛奶提供給有乳糖不耐症的賓客。"},{"en":"We have lactose-free options for each dessert.","zh-TW":"我們的每款甜點都有無乳糖選項。"}]', NULL, NULL, 4, 1808, NULL),
(1809, 'lady', '/ˈleɪdi/', 'noun', '{"zh-TW":["女士"],"en":["a polite word for a woman"]}', NULL, 'ladies and gentlemen / leading lady', '[{"en":"Ladies and gentlemen, welcome to the conference.","zh-TW":"各位女士先生，歡迎來到會議。"},{"en":"She is the leading lady of the industry.","zh-TW":"她是這個產業的領軍人物。"}]', '{"noun":"lady"}', NULL, 1, 1809, NULL),
(1810, 'lag', '/læɡ/', 'noun, verb', '{"zh-TW":["落後；延遲"],"en":["a delay or period of time between two events"]}', NULL, 'time lag / jet lag / lag behind', '[{"en":"There is often a lag between policy changes and results.","zh-TW":"政策變更和結果之間通常有時間差。"},{"en":"Our sales figures lag behind the competition.","zh-TW":"我們的銷售數字落後於競爭對手。"}]', '{"noun":"lag","verb":"lag"}', NULL, 1, 1810, NULL),
(1811, 'lake', '/leɪk/', 'noun', '{"zh-TW":["湖"],"en":["a large body of water surrounded by land"]}', NULL, 'lakeside / by the lake', '[{"en":"The resort is by the lake.","zh-TW":"度假村在湖邊。"},{"en":"The team-building event is at the lakeside.","zh-TW":"團建活動在湖畔舉行。"}]', '{"noun":"lake","noun2":"lakeside"}', NULL, 1, 1811, NULL),
(1812, 'land', '/lænd/', 'noun', '{"zh-TW":["土地；著陸"],"en":["an area of ground","to arrive on the ground"]}', NULL, 'land a deal / on land', '[{"en":"We landed a major contract.","zh-TW":"我們拿下了一個大合約。"},{"en":"They purchased land for the new office.","zh-TW":"他們為新辦公室購買了土地。"}]', '{"noun":"land","verb":"land","noun2":"landing","noun3":"landlord"}', NULL, 1, 1812, NULL),
(1813, 'landfill', '/ˈlændfɪl/', 'noun', '{"zh-TW":["垃圾掩埋場"],"en":["a site for the disposal of waste by burial"]}', NULL, 'reduce landfill waste / landfill gas', '[{"en":"Most household waste ends up in landfills.","zh-TW":"大多數家庭廢棄物最終進入垃圾掩埋場。"},{"en":"The city is working to divert waste away from landfills.","zh-TW":"市政府正致力於讓廢棄物不進入垃圾掩埋場。"}]', NULL, NULL, 3, 1813, NULL),
(1814, 'landlord', '/ˈlændlɔːrd/', 'noun', '{"zh-TW":["房東"],"en":["a person who rents land or property to others"]}', NULL, 'notify the landlord / landlord and tenant', '[{"en":"The landlord increased the rent by 10%.","zh-TW":"房東將租金提高了10%。"},{"en":"Please notify the landlord before moving out.","zh-TW":"搬出前請通知房東。"}]', '{"noun":"landlord, landlady"}', NULL, 3, 1814, NULL),
(1815, 'landmark', '/ˈlændmɑːrk/', 'noun, adjective', '{"zh-TW":["地標；里程碑"],"en":["an easily recognized feature; a significant event"]}', NULL, 'landmark decision/ruling/agreement', '[{"en":"The court made a landmark decision on privacy rights.","zh-TW":"法院就隱私權做出了里程碑式的裁決。"},{"en":"The tower is the city''s most famous landmark.","zh-TW":"這座塔是城市最著名的地標。"}]', '{"noun":"landmark"}', NULL, 3, 1815, NULL),
(1816, 'landscape', '/ˈlændskeɪp/', 'noun', '{"zh-TW":["風景；景觀","景觀；局勢"],"en":["the visible features of an area of land","the visible features of an area; the general situation"]}', '{"root":{"text":"land","meaning":"land (土地)"},"suffix":{"text":"scape","meaning":"view (景色)"},"logic":"土地的景色，即「風景」。"}', 'landscape painting / urban landscape; political/business landscape / landscape design', '[{"en":"The landscape in this region is breathtaking.","zh-TW":"這個地區的風景令人嘆為觀止。"},{"en":"She specializes in landscape photography.","zh-TW":"她專精風景攝影。"},{"en":"The business landscape has changed dramatically.","zh-TW":"商業格局發生了巨大的變化。"},{"en":"The landscape of the countryside is breathtaking.","zh-TW":"鄉村的景觀令人歎為觀止。"}]', '{"noun":"landscaping","verb":"landscape"}', NULL, 3, 1816, NULL),
(1817, 'language', '/ˈlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["語言"],"en":["a system of communication"]}', NULL, 'body language / language barrier', '[{"en":"The language barrier made negotiations difficult.","zh-TW":"語言障礙使談判變得困難。"},{"en":"She speaks three languages fluently.","zh-TW":"她流利地說三種語言。"}]', '{"noun":"language","adjective":"linguistic","noun2":"linguistics"}', NULL, 3, 1817, NULL),
(1818, 'large', '/lɑːrdʒ/', 'adjective', '{"zh-TW":["大的；大規模的"],"en":["big in size or amount"]}', NULL, 'at large / by and large', '[{"en":"By and large, the plan was successful.","zh-TW":"總的來說，計畫是成功的。"},{"en":"We serve large corporate clients.","zh-TW":"我們服務大型企業客戶。"}]', '{"adjective":"large","adverb":"largely","verb":"enlarge","noun":"enlargement"}', NULL, 2, 1818, NULL),
(1819, 'large-scale', '/lɑːrdʒ skeɪl/', 'adjective', '{"zh-TW":["大規模的"],"en":["involving a large number of people, resources, or activities"]}', NULL, 'large-scale operation / large-scale project / large-scale investment', '[{"en":"The large-scale infrastructure project required coordinated government support.","zh-TW":"大規模基礎設施項目需要協調一致的政府支持。"},{"en":"Large-scale manufacturing requires significant capital investment.","zh-TW":"大規模製造需要大量的資本投資。"}]', NULL, NULL, 4, 1819, NULL),
(1820, 'last', '/lɑːst/', 'adjective', '{"zh-TW":["最後的；上一個；持續"],"en":["coming after all others","most recent","to continue"]}', NULL, 'at last / last resort', '[{"en":"As a last resort, we may outsource.","zh-TW":"作為最後手段，我們可能外包。"},{"en":"The meeting lasted two hours.","zh-TW":"會議持續了兩個小時。"}]', '{"adjective":"last","verb":"last","adverb":"lastly","adjective2":"lasting"}', NULL, 1, 1820, NULL),
(1821, 'late', '/leɪt/', 'adjective', '{"zh-TW":["遲的；晚的"],"en":["after the expected time","near the end"]}', NULL, 'too late / late fee', '[{"en":"A late fee will be charged after the due date.","zh-TW":"逾期將收取滯納金。"},{"en":"Sorry I am late for the meeting.","zh-TW":"抱歉我開會遲到了。"}]', '{"adjective":"late","adverb":"lately","adverb2":"late","noun":"lateness"}', NULL, 1, 1821, NULL),
(1822, 'latest', 'ˈleɪtɪst', 'adjective', '{"zh-TW":["最新的；最近的","最晚的"],"en":["most recent","up to date"]}', NULL, 'latest version/latest news', '[{"en":"Please download the latest version.","zh-TW":"請下載最新版本。"}]', '{"adverb":"lately"}', NULL, 2, 1822, NULL),
(1823, 'latitude', '/ˈlætɪtjuːd/', 'noun', '{"zh-TW":["【主要意義】緯度","【次要意義】自由度；寬容度；行動或表達的自由空間"],"en":["[primary] the distance north or south of the equator","[secondary] freedom from restrictions; scope for action or thought"]}', NULL, 'give someone latitude / allow latitude / considerable latitude', '[{"en":"The manager gave her team considerable latitude in choosing their approach.","zh-TW":"經理給了她的團隊相當大的自由度來選擇他們的方法。"},{"en":"Journalists need latitude to investigate without interference.","zh-TW":"記者需要在不受干擾的情況下進行調查的自由度。"},{"en":"The new policy allows employees more latitude in their work schedules.","zh-TW":"新政策給予員工在工作時間安排上更多的靈活度。"}]', '{"adjective":"latitudinal"}', '除地理上的「緯度」外，latitude 在商業或管理語境中指「靈活度/自由裁量空間」，TOEIC 閱讀測驗中常見於描述管理或決策的文章。', 3, 1823, NULL),
(1824, 'laugh', '/læf/', 'verb', '{"zh-TW":["笑"],"en":["to make sounds showing amusement"]}', NULL, 'laugh at / have a laugh', '[{"en":"Don''t laugh at others'' mistakes.","zh-TW":"不要嘲笑別人的錯誤。"},{"en":"We had a good laugh at the team dinner.","zh-TW":"我們在團隊晚餐上笑得很開心。"}]', '{"verb":"laugh","noun":"laugh","noun2":"laughter"}', NULL, 2, 1824, NULL),
(1825, 'launch', '/lɔːntʃ/', 'verb', '{"zh-TW":["推出；發射","發射；推出；發起"],"en":["to start or introduce something new","to send into the air","to start or introduce something new; to send into the air"]}', '{"root":{"text":"launch","meaning":"throw (投擲)"},"logic":"源自古法語 lanchier（投擲），指推出新事物。"}', 'launch a product / launch a campaign / rocket launch; launch a product/campaign/website', '[{"en":"The company will launch a new product next week.","zh-TW":"公司下週將推出新產品。"},{"en":"NASA launched a satellite into orbit.","zh-TW":"NASA發射了一顆衛星進入軌道。"},{"en":"The company will launch its new product next month.","zh-TW":"公司將於下個月推出新產品。"},{"en":"They launched a marketing campaign on social media.","zh-TW":"他們在社群媒體上發起了行銷活動。"}]', '{"noun":"launch","verb":"launch"}', NULL, 2, 1825, 148),
(1826, 'law', '/lɔː/', 'noun', '{"zh-TW":["法律；法規"],"en":["rules made by a government"]}', NULL, 'break/obey the law / by law / law firm', '[{"en":"It is against the law to discriminate based on gender.","zh-TW":"基於性別的歧視是違法的。"},{"en":"She works for a prestigious law firm.","zh-TW":"她在一家知名律師事務所工作。"}]', '{"noun":"law, lawyer, lawsuit","adjective":"lawful, legal"}', NULL, 1, 1826, NULL),
(1827, 'lawsuit', '/ˈlɔːsuːt/', 'noun', '{"zh-TW":["訴訟"],"en":["a legal case brought to court"]}', NULL, 'file a lawsuit / class-action lawsuit', '[{"en":"She filed a lawsuit against the company.","zh-TW":"她對公司提起了訴訟。"},{"en":"The lawsuit was settled out of court.","zh-TW":"訴訟在庭外和解了。"}]', NULL, NULL, 3, 1827, NULL),
(1828, 'layoff', '/ˈleɪɒf/', 'noun', '{"zh-TW":["裁員；暫時解雇"],"en":["the temporary or permanent termination of employee jobs"]}', NULL, 'mass layoff / layoff announcement / avoid layoffs', '[{"en":"The company announced layoffs affecting 10% of its workforce.","zh-TW":"公司宣布裁員，影響10%的員工。"},{"en":"Thousands of employees received layoff notices last week.","zh-TW":"上週數千名員工收到了裁員通知。"}]', '{"verb":"lay off"}', NULL, 2, 1828, NULL),
(1829, 'layout', '/ˈleɪaʊt/', 'noun', '{"zh-TW":["佈局；版面設計"],"en":["the way things are arranged in a space"]}', NULL, 'office layout / page layout / floor layout', '[{"en":"The office layout was redesigned for better collaboration.","zh-TW":"辦公室佈局被重新設計以促進更好的合作。"},{"en":"She designed the layout of the new brochure.","zh-TW":"她設計了新宣傳冊的版面。"}]', '{"noun":"layout","verb":"lay out"}', NULL, 2, 1829, NULL),
(1830, 'layover', '/ˈleɪoʊvər/', 'noun', '{"zh-TW":["中途停留；過境停留"],"en":["a period of rest during a journey"]}', NULL, 'short layover / overnight layover', '[{"en":"We have a four-hour layover in Frankfurt.","zh-TW":"我們在法蘭克福有四小時的過境停留。"},{"en":"Use your layover to explore the city.","zh-TW":"利用過境停留時間遊覽城市。"}]', NULL, NULL, 3, 1830, NULL),
(1831, 'lead', '/liːd/', 'verb, noun', '{"zh-TW":["領導；帶領","領先；主導地位"],"en":["to guide or direct; to be in charge","a position of advantage"]}', NULL, 'lead a team/project / take the lead', '[{"en":"She leads a team of ten engineers.","zh-TW":"她領導一個十人的工程師團隊。"},{"en":"Our company has taken the lead in innovation.","zh-TW":"我們公司在創新方面處於領先地位。"}]', '{"noun":"lead, leader, leadership","verb":"lead","adjective":"leading"}', NULL, 1, 1831, NULL),
(1832, 'leadership', '/ˈliːdərʃɪp/', 'noun', '{"zh-TW":["領導力；領導層"],"en":["the quality of being a leader; the group of leaders"]}', NULL, 'strong leadership / leadership skills / under the leadership of', '[{"en":"Strong leadership is essential for organizational success.","zh-TW":"強有力的領導對組織成功至關重要。"},{"en":"Under her leadership, the company doubled its revenue.","zh-TW":"在她的領導下，公司收入翻了一番。"}]', '{"noun":"leadership, leader","verb":"lead","adjective":"leading"}', NULL, 4, 1832, 382),
(1833, 'league', '/liːɡ/', 'noun', '{"zh-TW":["聯盟；聯賽"],"en":["a group of sports teams that compete"]}', NULL, 'major league / out of one''s league', '[{"en":"He plays in the major leagues.","zh-TW":"他在大聯盟打球。"},{"en":"That restaurant is out of my league.","zh-TW":"那家餐廳不是我消費得起的。"}]', NULL, NULL, 2, 1833, NULL),
(1834, 'lean', '/liːn/', 'adjective, verb', '{"zh-TW":["精簡的；瘦的","傾斜；依靠"],"en":["thin; efficient with minimal waste","to incline or rest against"]}', NULL, 'lean manufacturing / lean budget / lean on', '[{"en":"The company adopted lean manufacturing practices.","zh-TW":"公司採用了精實生產方式。"},{"en":"We need to run a lean operation to survive.","zh-TW":"我們需要精簡營運才能生存。"}]', '{"noun":"lean","adjective":"lean","verb":"lean"}', NULL, 1, 1834, NULL),
(1835, 'learn', '/lɜːrn/', 'verb', '{"zh-TW":["學習；得知"],"en":["to gain knowledge","to find out"]}', NULL, 'learn from / learn the ropes', '[{"en":"We learn from our mistakes.","zh-TW":"我們從錯誤中學習。"},{"en":"It takes time to learn the ropes.","zh-TW":"熟悉工作需要時間。"}]', '{"verb":"learn","noun":"learner","noun2":"learning","adjective":"learned"}', NULL, 2, 1835, NULL),
