(1837, 'lease', '/liːs/', 'noun, verb', '{"zh-TW":["租約；租賃"],"en":["a contract to use property for a specified time"]}', NULL, 'sign/renew a lease / lease agreement', '[{"en":"The office lease expires at the end of the year.","zh-TW":"辦公室租約年底到期。"},{"en":"We leased the equipment for three years.","zh-TW":"我們租賃了設備三年。"}]', '{"noun":"lease, leaseholder","verb":"lease"}', NULL, 2, 1837, 149),
(1838, 'leasehold', '/ˈliːshəʊld/', 'noun', '{"zh-TW":["租賃產權；租賃持有"],"en":["the holding of property on a long-term lease"]}', NULL, 'leasehold property / leasehold agreement', '[{"en":"The company occupies the office on a leasehold basis.","zh-TW":"公司以租賃產權方式佔用辦公室。"},{"en":"Leasehold agreements typically run for 99 years.","zh-TW":"租賃產權協議通常持續99年。"}]', '{"adjective":"leasehold"}', NULL, 3, 1838, NULL),
(1839, 'leave', '/liːv/', 'noun, verb', '{"zh-TW":["假期；休假","離開"],"en":["time when you are allowed to be away from work","to go away from"]}', NULL, 'on leave / sick leave / maternity leave', '[{"en":"She is on maternity leave until March.","zh-TW":"她休產假到三月。"},{"en":"He took a leave of absence for personal reasons.","zh-TW":"他因個人原因請了假。"}]', '{"noun":"leave","verb":"leave"}', NULL, 2, 1839, NULL),
(1840, 'lecture', '/ˈlɛktʃər/', 'noun', '{"zh-TW":["講座；演講"],"en":["a talk given to teach people","an educational talk to an audience"]}', NULL, 'attend a lecture / give a lecture; give/attend a lecture / lecture hall', '[{"en":"The professor gave an interesting lecture.","zh-TW":"教授做了一場有趣的演講。"},{"en":"I have a lecture at 2 PM.","zh-TW":"我下午2點有一堂課。"},{"en":"Professor Smith gave a lecture on economics.","zh-TW":"史密斯教授做了一場經濟學講座。"},{"en":"The lecture was attended by over 200 students.","zh-TW":"超過200名學生參加了講座。"}]', '{"verb":"lecture","noun2":"lecturer","noun":"lecture, lecturer"}', NULL, 3, 1840, NULL),
(1841, 'ledger', '/ˈlɛdʒər/', 'noun', '{"zh-TW":["帳本；分類帳"],"en":["a book or digital record of all financial transactions"]}', NULL, 'general ledger / ledger entry / accounts ledger', '[{"en":"All transactions are posted to the general ledger.","zh-TW":"所有交易都過帳至總分類帳。"},{"en":"The bookkeeper reconciled the ledger at month-end.","zh-TW":"簿記員在月底對帳本進行了核對。"}]', '{"plural":"ledgers"}', NULL, 2, 1841, NULL),
(1842, 'legal', '/ˈliːɡl/', 'adjective', '{"zh-TW":["法律的；合法的"],"en":["relating to law; permitted by law"]}', NULL, 'legal advice/action/requirement', '[{"en":"You should seek legal advice before signing.","zh-TW":"簽署前你應該尋求法律建議。"},{"en":"The company took legal action against the competitor.","zh-TW":"公司對競爭對手提起了法律訴訟。"}]', '{"noun":"legality","adjective":"legal, illegal","adverb":"legally","verb":"legalize"}', NULL, 2, 1842, 383),
(1843, 'legislation', '/ˌlɛdʒɪsˈleɪʃən/', 'noun', '{"zh-TW":["立法；法規"],"en":["laws considered as a group","a law or set of laws made by a government"]}', NULL, 'pass legislation / new legislation; introduce/pass legislation / environmental legislation', '[{"en":"New legislation was passed yesterday.","zh-TW":"新的法規昨天通過了。"},{"en":"The legislation aims to reduce pollution.","zh-TW":"該法規旨在減少污染。"},{"en":"New legislation was passed to protect consumers.","zh-TW":"通過了新的立法以保護消費者。"},{"en":"The legislation will take effect next month.","zh-TW":"該法規將於下個月生效。"}]', '{"verb":"legislate","noun2":"legislator","adjective":"legislative","noun":"legislation, legislator, legislature"}', NULL, 4, 1843, 589),
(1844, 'legitimate', '/lɪˈdʒɪtɪmət/', 'adjective', '{"zh-TW":["合法的；正當的"],"en":["conforming to the law; reasonable"]}', NULL, 'legitimate business/concern/reason', '[{"en":"This is a perfectly legitimate business.","zh-TW":"這是一家完全合法的企業。"},{"en":"Employees have legitimate concerns about job security.","zh-TW":"員工對工作保障有正當的擔憂。"}]', '{"noun":"legitimacy","adjective":"legitimate","verb":"legitimize","adverb":"legitimately"}', NULL, 4, 1844, NULL),
(1845, 'lend', '/lend/', 'verb', '{"zh-TW":["借出；貸款"],"en":["to give something to someone temporarily"]}', NULL, 'lend money / lend support/assistance', '[{"en":"The bank agreed to lend us the money.","zh-TW":"銀行同意借錢給我們。"},{"en":"Could you lend me your notes from the meeting?","zh-TW":"你能把會議記錄借我看看嗎？"}]', '{"noun":"lender, lending","verb":"lend"}', NULL, 1, 1845, NULL),
(1846, 'lender', '/ˈlendər/', 'noun', '{"zh-TW":["貸款方；放款人"],"en":["a bank or other organization that provides money to borrowers"]}', NULL, 'approach a lender / negotiate with the lender', '[{"en":"The company approached multiple lenders to secure the best rate.","zh-TW":"公司與多家貸款方接洽以獲得最佳利率。"},{"en":"The lender required collateral before approving the mortgage.","zh-TW":"貸款方在批准抵押貸款前要求提供抵押品。"}]', '{"verb":"lend","opposite":"borrower"}', NULL, 2, 1846, NULL),
(1847, 'lenient', '/ˈliːniənt/', 'adjective', '{"zh-TW":["寬大的；仁慈的"],"en":["not strict in punishing or enforcing rules"]}', NULL, 'lenient policy/approach/sentence', '[{"en":"The company has a lenient policy on remote work.","zh-TW":"公司對遠端工作有寬鬆的政策。"},{"en":"The judge was lenient with first-time offenders.","zh-TW":"法官對初犯者較為寬大。"}]', '{"noun":"leniency","adjective":"lenient","adverb":"leniently"}', NULL, 3, 1847, NULL),
(1848, 'lessee', '/leˈsiː/', 'noun', '{"zh-TW":["承租人；租客"],"en":["a person who holds a property under a lease"]}', NULL, 'lessee obligations / lessee rights / commercial lessee', '[{"en":"The lessee must maintain the property in good condition.","zh-TW":"承租人必須保持物業處於良好狀態。"},{"en":"As the lessee, she was responsible for all utility costs.","zh-TW":"作為承租人，她負責所有水電費。"}]', '{"opposite":"lessor"}', NULL, 2, 1848, NULL),
(1849, 'lesson', '/ˈlɛsən/', 'noun', '{"zh-TW":["課程；教訓"],"en":["a period of teaching","something learned from experience"]}', NULL, 'learn a lesson / lessons learned', '[{"en":"We documented lessons learned from the project.","zh-TW":"我們記錄了專案的經驗教訓。"},{"en":"That failure taught us a valuable lesson.","zh-TW":"那次失敗教了我們寶貴的一課。"}]', '{"noun":"lesson"}', NULL, 2, 1849, NULL);
