(1854, 'leverage', '/ˈlevərɪdʒ/', 'noun, verb', '{"zh-TW":["槓桿；影響力","利用；借助"],"en":["influence or advantage; borrowing for investment","to use to maximum advantage"]}', NULL, 'leverage resources/technology/data', '[{"en":"We should leverage our existing technology.","zh-TW":"我們應該充分利用現有技術。"},{"en":"The company has significant leverage in negotiations.","zh-TW":"公司在談判中有很大的影響力。"}]', '{"noun":"leverage","verb":"leverage"}', NULL, 3, 1854, 696),
