(1856, 'levy', '/ˈlevi/', 'noun, verb', '{"zh-TW":["徵收；稅款"],"en":["a tax or fee imposed by a government"]}', NULL, 'levy a tax/fine / impose a levy', '[{"en":"The government levied a new tax on imports.","zh-TW":"政府對進口商品徵收了新稅。"},{"en":"A levy was imposed on carbon emissions.","zh-TW":"對碳排放徵收了稅款。"}]', '{"noun":"levy","verb":"levy"}', NULL, 1, 1856, NULL),
(1857, 'liability', '/ˌlaɪəˈbɪləti/', 'noun', '{"zh-TW":["責任；負債；不利因素"],"en":["legal responsibility; debts; a disadvantage"]}', NULL, 'limited liability / financial liability', '[{"en":"The company has limited liability for damages.","zh-TW":"公司對損害承擔有限責任。"},{"en":"Total liabilities exceeded assets by $2 million.","zh-TW":"總負債超過資產200萬美元。"}]', '{"noun":"liability","adjective":"liable"}', NULL, 3, 1857, 384),
