(1860, 'librarian', '/laɪˈbrɛriən/', 'noun', '{"zh-TW":["圖書館員"],"en":["a person who works in a library"]}', NULL, 'school librarian / ask the librarian', '[{"en":"The librarian helped me find the book.","zh-TW":"圖書館員幫我找到了那本書。"},{"en":"She has worked as a librarian for ten years.","zh-TW":"她當圖書館員已經十年了。"}]', '{"noun2":"library"}', NULL, 3, 1860, NULL),
(1861, 'library', '/ˈlaɪbrɛri/', 'noun', '{"zh-TW":["圖書館"],"en":["a building or room with books for reading or borrowing"]}', NULL, 'public library / digital library', '[{"en":"The company has a digital library for employees.","zh-TW":"公司為員工設有數位圖書館。"},{"en":"I researched at the public library.","zh-TW":"我在公共圖書館做了研究。"}]', '{"noun":"library","noun2":"librarian"}', NULL, 3, 1861, NULL),
(1862, 'license', '/ˈlaɪsns/', 'noun, verb', '{"zh-TW":["執照；許可證","授權；許可"],"en":["official permission to do something","to grant a license"]}', NULL, 'driver''s license / license agreement / software license', '[{"en":"You need a license to operate this machinery.","zh-TW":"你需要執照才能操作這台機器。"},{"en":"The software is licensed for commercial use.","zh-TW":"該軟體已獲授權供商業使用。"}]', '{"noun":"license, licensee","verb":"license","adjective":"licensed"}', NULL, 3, 1862, 385),
(1863, 'licensing', '/ˈlaɪsənsɪŋ/', 'noun', '{"zh-TW":["授權；許可"],"en":["granting permission to another party to use intellectual property or technology"]}', NULL, 'licensing agreement / licensing deal / technology licensing / licensing revenue', '[{"en":"Licensing the technology was more profitable than manufacturing.","zh-TW":"授權技術比自行製造更有利可圖。"},{"en":"The licensing agreement allowed the brand to expand globally.","zh-TW":"授權協議允許品牌在全球擴張。"}]', '{"verb":"license","noun":"licensor","adjective":"licensed"}', NULL, 3, 1863, NULL),
