(1865, 'life', '/laɪf/', 'noun', '{"zh-TW":["生命；生活"],"en":["the existence of a person","the way someone lives"]}', NULL, 'work-life balance / shelf life', '[{"en":"Work-life balance is important to us.","zh-TW":"工作與生活的平衡對我們很重要。"},{"en":"The product has a shelf life of two years.","zh-TW":"產品的保質期為兩年。"}]', '{"noun":"life","adjective":"lifelong","noun2":"lifestyle","noun3":"lifetime"}', NULL, 1, 1865, NULL),
(1866, 'light', '/laɪt/', 'noun', '{"zh-TW":["【主要意義-名詞】光；燈光","【次要意義-形容詞】輕的；輕量的","【次要意義-形容詞】淺色的；明亮的","【次要意義-形容詞】不嚴格的；輕描淡寫的","【次要意義-副詞】輕裝地；只帶少量行李"],"en":["[primary - noun] electromagnetic radiation that makes things visible","[secondary - adjective] not heavy in weight","[secondary - adjective] pale in color","[secondary - adjective] not serious or severe","[secondary - adverb] with little luggage"]}', NULL, 'light sentence / light duties / travel light / light reading / in a new light', '[{"en":"The judge gave a surprisingly light sentence for the financial crime.","zh-TW":"法官對這起金融犯罪給予了出人意料的輕判。"},{"en":"Employees on light duties are assigned simpler administrative tasks.","zh-TW":"輕度工作的員工被分配較簡單的行政任務。"},{"en":"Business travelers prefer to travel light for short trips.","zh-TW":"商務旅客短途出行時更喜歡輕裝上陣。"}]', '{"noun":"lighting, lightness","verb":"lighten","adjective":"lightweight"}', 'light 作形容詞有多個次要意義：「不嚴格的」（light sentence）、「輕量的」（light duties）等，片語 in a new light = 以新眼光看待，常見於 TOEIC 描述判決或職責的語境。', 2, 1866, NULL),
(1867, 'lightning', '/ˈlaɪtnɪŋ/', 'noun', '{"zh-TW":["閃電"],"en":["a flash of bright light in the sky during a storm"]}', '{"root":{"text":"light","meaning":"light (光)"},"suffix":{"text":"-ning","meaning":"action (動作)"},"logic":"天空中光的動作，即「閃電」。"}', 'lightning bolt / lightning strike / lightning rod', '[{"en":"Lightning struck the old tree in the park.","zh-TW":"閃電擊中了公園裡的老樹。"},{"en":"Never stand under a tree during a lightning storm.","zh-TW":"閃電暴風雨時千萬不要站在樹下。"}]', NULL, NULL, 3, 1867, NULL),
(1868, 'likewise', '/ˈlaɪkwaɪz/', 'adverb', '{"zh-TW":["同樣地；也"],"en":["in the same way; also"]}', NULL, 'do likewise / likewise, ...', '[{"en":"The first team finished early, and the second did likewise.","zh-TW":"第一組提前完成了，第二組也是如此。"},{"en":"Likewise, we must consider the long-term effects.","zh-TW":"同樣地，我們必須考慮長期影響。"}]', '{"adverb":"likewise"}', NULL, 3, 1868, NULL),
