(1871, 'line', '/laɪn/', 'noun', '{"zh-TW":["線；排；產品線"],"en":["a long narrow mark; a row of people; a range of products"]}', NULL, 'product line / bottom line / assembly line', '[{"en":"The company expanded its product line.","zh-TW":"公司擴大了其產品線。"},{"en":"The bottom line is that we need more revenue.","zh-TW":"重點是我們需要更多收入。"}]', '{"noun":"line","verb":"line","adjective":"linear"}', NULL, 1, 1871, NULL),
(1872, 'link', '/lɪŋk/', 'noun, verb', '{"zh-TW":["連結；聯繫"],"en":["a connection between things"]}', NULL, 'link between / link to / a direct link', '[{"en":"There is a clear link between education and income.","zh-TW":"教育和收入之間有明確的關聯。"},{"en":"Please click the link below for more details.","zh-TW":"請點擊下面的連結以獲取更多詳情。"}]', '{"noun":"link, linkage","verb":"link"}', NULL, 1, 1872, NULL),
(1873, 'liquid', '/ˈlɪkwɪd/', 'noun, adjective', '{"zh-TW":["液體","液態的；流動的"],"en":["a substance that flows freely","in the form of a liquid; easily converted to cash"]}', NULL, 'liquid assets / liquid state', '[{"en":"The company needs more liquid assets.","zh-TW":"公司需要更多的流動資產。"},{"en":"Water is a liquid at room temperature.","zh-TW":"水在室溫下是液體。"}]', '{"noun":"liquid, liquidity","adjective":"liquid","verb":"liquidate"}', NULL, 2, 1873, NULL),
