(1875, 'liquidation', '/ˌlɪkwɪˈdeɪʃən/', 'noun', '{"zh-TW":["清算；倒閉"],"en":["the winding up of a company and sale of its assets"]}', NULL, 'enter liquidation / voluntary liquidation', '[{"en":"The company entered voluntary liquidation after years of losses.","zh-TW":"公司在多年虧損後進入自願清算。"},{"en":"Assets are distributed to creditors during liquidation.","zh-TW":"在清算期間，資產被分配給債權人。"}]', '{"verb":"liquidate","adjective":"liquidated"}', NULL, 4, 1875, 591),
